// LES TEXTES DE L'INTERFACE, EN SEPT LANGUES
//
// ⚠️ LE FRANÇAIS EST LA SOURCE. Le type `Traduction` impose `fr` et rend les
// autres langues facultatives : une clé peut donc vivre ici avec seulement sa
// version française, et les six autres retomberont dessus — jamais de trou à
// l'écran. C'est ce qui permet d'ajouter un écran sans traduire sept langues
// dans la même respiration.
//
// ⚠️ CE QUI N'EST PAS ICI, ET POURQUOI. Le récit du Maître du Jeu, les
// situations, les tweets, les messages privés et les commentaires de match sont
// ÉCRITS À L'EXÉCUTION par l'IA locale. On ne les traduit pas : on demande au modèle
// d'écrire directement dans la langue du joueur (`consigneDeLangue`,
// lib/i18n.ts). C'est plus juste — un tweet traduit sonne toujours faux — et
// ça ne coûte pas un octet de plus dans le bundle.
//
// Convention des clés : `zone.element`. Un suffixe `.pluriel` fournit la forme
// plurielle utilisée par `tn()`.

import type { Traduction } from '../lib/i18n';
import { TEXTES_ECRANS } from './textesEcrans';
import { TEXTES_CONTENU } from './textesContenu';
import { TEXTES_AUTO } from './textesAuto';
import { TEXTES_SUPPLEMENTAIRES } from './textesSupplementaires';
import { TEXTES_TROPHEES } from './textesTrophees';
import { TEXTES_SOCIAUX } from './textesSociaux';
import { TEXTES_MATCH } from './textesMatch';

// ⚠️ LA TRADUCTION AUTOMATIQUE PASSE EN DERNIER — c'est-à-dire qu'elle est
// écrasée par tout le reste. `scripts/traduire.ts` remplit les langues
// générées historiquement dans `textesAuto.ts` ; le fusionner ici
// avec la priorité la plus BASSE garantit deux choses : une traduction écrite à
// la main gagne toujours, et relancer le script ne peut rien abîmer. Corriger
// une tournure, c'est simplement l'écrire dans le fichier normal.
//
// ⚠️ On ne fusionne PAS clé par clé : une entrée automatique complète une clé
// qui n'a que son français, elle ne vient jamais se mêler à une entrée
// existante. Le `Object.assign` ci-dessous respecte ça — la valeur de droite
// remplace entièrement celle de gauche.
function fusionner(base: Record<string, Traduction>): Record<string, Traduction> {
  const sortie: Record<string, Traduction> = {};
  for (const [k, auto] of Object.entries(TEXTES_AUTO)) {
    const humaine = base[k];
    // Une clé automatique sans français dans la base n'existe pas : on l'ignore
    // plutôt que d'inventer une entrée sans source.
    if (!humaine) continue;
    sortie[k] = { ...auto, ...humaine };
  }
  return { ...base, ...sortie };
}

