  // --- RÉGLAGES -----------------------------------------------------------
  'reg.titre': { fr: 'Maître du Jeu et confort de jeu', en: 'Game Master and comfort settings', es: 'Máster y ajustes de juego', it: 'Master e comfort di gioco', de: 'Spielleiter und Spielkomfort', pt: 'Mestre do Jogo e conforto de jogo', ja: 'ゲームマスターとプレイ設定' },
  'reg.eyebrow': { fr: 'MOTEUR DU MAÎTRE DU JEU', en: 'GAME MASTER ENGINE', es: 'MOTOR DEL MÁSTER', it: 'MOTORE DEL MASTER', de: 'SPIELLEITER-ENGINE', pt: 'MOTOR DO MESTRE DO JOGO', ja: 'ゲームマスター エンジン' },
  'reg.iaAide': { fr: 'Le Maître du Jeu écrit tes scènes à la volée. Si le quota est atteint, le jeu bascule tout seul sur ses situations pré-écrites, puis revient dès qu’il se libère.', en: 'The Game Master writes your scenes on the fly. If the quota runs out, the game silently switches to its pre-written situations and returns as soon as it frees up.', es: 'El Máster escribe tus escenas al vuelo. Si se agota la cuota, el juego pasa solo a sus situaciones preescritas y vuelve en cuanto se libera.', it: 'Il Master scrive le tue scene al volo. Se la quota si esaurisce, il gioco passa da solo alle situazioni già scritte e torna appena si libera.', de: 'Der Spielleiter schreibt deine Szenen live. Ist das Kontingent erschöpft, wechselt das Spiel von selbst zu vorgeschriebenen Situationen und kehrt zurück, sobald es wieder frei ist.', pt: 'O Mestre do Jogo escreve as tuas cenas em direto. Se a quota acabar, o jogo passa sozinho para as situações pré-escritas e regressa assim que ficar livre.', ja: 'ゲームマスターがその場でシーンを書きます。上限に達すると自動的に用意済みのシーンに切り替わり、回復すると自動で戻ります。' },
  'reg.iaMJ': { fr: 'Maître du Jeu', en: 'Game Master', es: 'Máster', it: 'Master', de: 'Spielleiter', pt: 'Mestre do Jogo', ja: 'ゲームマスター' },
  'reg.iaPrete': { fr: 'Prête', en: 'Ready', es: 'Lista', it: 'Pronta', de: 'Bereit', pt: 'Pronta', ja: '準備完了' },
  'reg.iaQuota': { fr: 'Quota atteint', en: 'Quota reached', es: 'Cuota agotada', it: 'Quota raggiunta', de: 'Kontingent erreicht', pt: 'Quota atingida', ja: '上限に到達' },
  'reg.iaInactive': { fr: 'Inactive', en: 'Inactive', es: 'Inactiva', it: 'Inattiva', de: 'Inaktiv', pt: 'Inativa', ja: '無効' },
  'reg.iaSansCle': { fr: 'Indisponible', en: 'Unavailable', es: 'No disponible', it: 'Non disponibile', de: 'Nicht verfügbar', pt: 'Indisponível', ja: '利用不可' },
  'reg.iaPreteAide': { fr: 'Tes scènes, les publications de L’Ovale et le coaching en direct sont écrits pour toi, à la volée.', en: 'Your scenes, The Oval’s posts and live coaching are written for you, on the fly.', es: 'Tus escenas, las publicaciones de El Oval y el coaching en directo se escriben para ti, al vuelo.', it: 'Le tue scene, i post de L’Ovale e il coaching dal vivo sono scritti per te, al volo.', de: 'Deine Szenen, die Beiträge von The Oval und das Live-Coaching werden für dich geschrieben, in Echtzeit.', pt: 'As tuas cenas, as publicações do Oval e o coaching em direto são escritos para ti, em direto.', ja: 'シーン、オーバルの投稿、ライブ指示はすべてその場で生成されます。' },
  'reg.iaQuotaAide': { fr: 'Le jeu continue avec ses situations pré-écrites. Le Maître du Jeu revient', en: 'The game continues with its pre-written situations. The Game Master returns', es: 'El juego continúa con sus situaciones preescritas. El Máster vuelve', it: 'Il gioco continua con le sue situazioni già scritte. Il Master torna', de: 'Das Spiel läuft mit vorgeschriebenen Situationen weiter. Der Spielleiter kehrt zurück', pt: 'O jogo continua com as suas situações pré-escritas. O Mestre do Jogo regressa', ja: '用意済みのシーンでゲームは続きます。ゲームマスターの復帰:' },
  'reg.iaSansCleAide': { fr: 'Aucune clé disponible pour l’instant : le jeu tourne avec ses situations pré-écrites.', en: 'No key available right now: the game runs on its pre-written situations.', es: 'No hay clave disponible ahora mismo: el juego funciona con sus situaciones preescritas.', it: 'Nessuna chiave disponibile al momento: il gioco gira con le situazioni già scritte.', de: 'Derzeit kein Schlüssel verfügbar: Das Spiel läuft mit vorgeschriebenen Situationen.', pt: 'Sem chave disponível de momento: o jogo funciona com as situações pré-escritas.', ja: '現在キーが利用できません。用意済みのシーンでプレイできます。' },
  'reg.iaDesactiveeAide': { fr: 'Tu joues avec les situations, évènements et commentaires pré-écrits. Le jeu reste entier.', en: 'You are playing with pre-written situations, events and comments. The game stays complete.', es: 'Juegas con situaciones, eventos y comentarios preescritos. El juego sigue completo.', it: 'Giochi con situazioni, eventi e commenti già scritti. Il gioco resta completo.', de: 'Du spielst mit vorgeschriebenen Situationen, Ereignissen und Kommentaren. Das Spiel bleibt vollständig.', pt: 'Jogas com situações, eventos e comentários pré-escritos. O jogo continua completo.', ja: '用意済みのシーン・イベント・コメントでプレイします。内容はすべて遊べます。' },
  'reg.iaRepriseMinutes': { fr: 'dans {n} min.', en: 'in {n} min.', es: 'en {n} min.', it: 'tra {n} min.', de: 'in {n} Min.', pt: 'dentro de {n} min.', ja: '約{n}分後' },
  'reg.iaRepriseBientot': { fr: 'dans moins d’une minute.', en: 'in less than a minute.', es: 'en menos de un minuto.', it: 'tra meno di un minuto.', de: 'in weniger als einer Minute.', pt: 'em menos de um minuto.', ja: '1分以内' },
