  'pub.emplacement': { fr: 'Emplacement publicitaire', en: 'Advertising slot', es: 'Espacio publicitario', it: 'Spazio pubblicitario', de: 'Werbeplatz', pt: 'Espaço publicitário', ja: '広告枠' },
  'pub.consentTitre': { fr: 'Publicité', en: 'Advertising', es: 'Publicidad', it: 'Pubblicità', de: 'Werbung', pt: 'Publicidade', ja: '広告' },
  'pub.consentTexte': { fr: 'Une bannière discrète, uniquement sur les écrans hors jeu, aide à payer l’hébergement. Jamais pendant une partie, jamais en plein écran. Tu peux refuser : le jeu est identique.', en: 'A discreet banner, only on out-of-game screens, helps pay for hosting. Never during play, never full screen. You can decline: the game is the same either way.', es: 'Un banner discreto, solo en pantallas fuera de la partida, ayuda a pagar el alojamiento. Nunca durante el juego ni a pantalla completa. Puedes rechazarlo: el juego es idéntico.', it: 'Un banner discreto, solo nelle schermate fuori dal gioco, aiuta a pagare l’hosting. Mai durante una partita, mai a schermo intero. Puoi rifiutare: il gioco è identico.', de: 'Ein dezentes Banner, nur auf Bildschirmen außerhalb des Spiels, hilft beim Hosting. Nie während des Spiels, nie im Vollbild. Du kannst ablehnen – das Spiel bleibt gleich.', pt: 'Um banner discreto, apenas nos ecrãs fora do jogo, ajuda a pagar o alojamento. Nunca durante uma partida nem em ecrã inteiro. Podes recusar: o jogo é igual.', ja: 'ゲーム外の画面にのみ表示される控えめなバナーが、運営費の助けになります。プレイ中や全画面には出ません。拒否してもゲーム内容は変わりません。' },
  'pub.accepter': { fr: 'Accepter', en: 'Accept', es: 'Aceptar', it: 'Accetta', de: 'Annehmen', pt: 'Aceitar', ja: '同意する' },
  'pub.refuser': { fr: 'Refuser', en: 'Decline', es: 'Rechazar', it: 'Rifiuta', de: 'Ablehnen', pt: 'Recusar', ja: '拒否する' },
  'pub.reactiver': { fr: 'Activer les pubs récompensées', en: 'Turn on rewarded ads', es: 'Activar anuncios con recompensa', it: 'Attiva gli annunci con premio', de: 'Belohnte Werbung aktivieren', pt: 'Ativar anúncios com recompensa', ja: 'リワード広告を有効にする' },
  'pub.recompenseTitre': { fr: 'Pub récompensée', en: 'Rewarded ad', es: 'Anuncio con recompensa', it: 'Annuncio con premio', de: 'Belohnte Werbung', pt: 'Anúncio com recompensa', ja: 'リワード広告' },
  'pub.recompenseDetail': { fr: 'Regarde une courte pub, gagne {ovas} Ovas. Rien d’exclusif ne se cache derrière.', en: 'Watch a short ad, earn {ovas} Ovas. Nothing exclusive is locked behind it.', es: 'Mira un anuncio corto y gana {ovas} Ovas. Nada exclusivo está detrás.', it: 'Guarda un breve annuncio e guadagna {ovas} Ovas. Niente di esclusivo è nascosto dietro.', de: 'Sieh dir einen kurzen Spot an und erhalte {ovas} Ovas. Nichts Exklusives steckt dahinter.', pt: 'Vê um anúncio curto e ganha {ovas} Ovas. Nada de exclusivo está por trás.', ja: '短い広告を見て{ovas}オーヴァスを獲得。限定要素は一切ありません。' },
  'pub.restantes': { fr: '{n} sur {total} aujourd’hui', en: '{n} of {total} today', es: '{n} de {total} hoy', it: '{n} su {total} oggi', de: '{n} von {total} heute', pt: '{n} de {total} hoje', ja: '本日 {n}/{total} 回' },
