  'pub.gagne': { fr: '+{ovas} Ovas 🪙', en: '+{ovas} Ovas 🪙', es: '+{ovas} Ovas 🪙', it: '+{ovas} Ovas 🪙', de: '+{ovas} Ovas 🪙', pt: '+{ovas} Ovas 🪙', ja: '+{ovas} オーヴァス 🪙' },
  'pub.maisonTitre': { fr: 'Destiny Rugby', en: 'Destiny Rugby', es: 'Destiny Rugby', it: 'Destiny Rugby', de: 'Destiny Rugby', pt: 'Destiny Rugby', ja: 'Destiny Rugby' },
  'pub.maisonTexte': { fr: 'Aucune régie n’est branchée pour l’instant : voici un encart maison. Reste jusqu’au bout pour toucher tes Ovas — tu peux quitter quand tu veux.', en: 'No ad network is connected yet, so here is a house ad. Stay to the end to collect your Ovas — you can leave whenever you like.', es: 'Todavía no hay red publicitaria conectada: aquí va un anuncio propio. Quédate hasta el final para cobrar tus Ovas; puedes salir cuando quieras.', it: 'Nessun circuito pubblicitario è collegato: ecco un annuncio interno. Resta fino alla fine per incassare le tue Ovas — puoi uscire quando vuoi.', de: 'Es ist noch kein Werbenetzwerk angebunden – hier eine Eigenanzeige. Bleib bis zum Ende, um deine Ovas zu erhalten. Du kannst jederzeit abbrechen.', pt: 'Ainda não há rede publicitária ligada: aqui fica um anúncio da casa. Fica até ao fim para receberes as tuas Ovas — podes sair quando quiseres.', ja: '現在、広告ネットワークは未接続のため自社広告を表示しています。最後まで見るとオーヴァスがもらえます。いつでも終了できます。' },
  'pub.maisonTexteArticle': { fr: 'Aucune régie n’est branchée pour l’instant : voici un encart maison. Reste jusqu’au bout et le cosmétique est à toi — tu peux quitter quand tu veux.', en: 'No ad network is connected yet, so here is a house ad. Stay to the end and the cosmetic is yours — you can leave whenever you like.', es: 'Todavía no hay red publicitaria conectada: aquí va un anuncio propio. Quédate hasta el final y el cosmético es tuyo; puedes salir cuando quieras.', it: 'Nessun circuito pubblicitario è collegato: ecco un annuncio interno. Resta fino alla fine e il cosmetico è tuo — puoi uscire quando vuoi.', de: 'Es ist noch kein Werbenetzwerk angebunden – hier eine Eigenanzeige. Bleib bis zum Ende, und das Kosmetikteil gehört dir. Du kannst jederzeit abbrechen.', pt: 'Ainda não há rede publicitária ligada: aqui fica um anúncio da casa. Fica até ao fim e o cosmético é teu — podes sair quando quiseres.', ja: '現在、広告ネットワークは未接続のため自社広告を表示しています。最後まで見るとコスメが手に入ります。いつでも終了できます。' },
